import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../build/host.gen.ts';

const view = (status, task0, task1, retried0 = false, retried1 = false, processed = 0) => ({ status, task0, task1, retried0, retried1, processed });

test('initial', async () => {
  const h = await createHost();
  assert.deepEqual(await h.run(), view('idle', 'idle', 'idle'));
  assert.deepEqual(await h.worker('worker0'), { status: 'idle' });
  assert.equal(await h.worker('x'), null);
  assert.equal((await h.workDone('worker0', 1)).ok, false);
  assert.equal((await h.workDone('nobody', 1)).ok, false);
  assert.equal((await h.cancel()).ok, false);
});

test('both complete', async () => {
  const h = await createHost();
  assert.deepEqual(await h.start(), { ok: true });
  assert.equal((await h.start()).ok, false);
  assert.deepEqual(await h.run(), view('running', 'assigned', 'assigned'));
  const msgs = await h.inFlight();
  assert.equal(msgs.length, 2);
  assert.deepEqual(msgs.map((m) => [m.from, m.to, m.action, m.data]).sort(), [['run', 'worker0', 'Assign', {}], ['run', 'worker1', 'Assign', {}]]);
  await h.deliverAll();
  assert.deepEqual(await h.worker('worker1'), { status: 'busy' });
  assert.equal((await h.workDone('worker0', 0)).ok, false);
  assert.equal((await h.workDone('worker0', 3)).ok, false);
  assert.deepEqual(await h.worker('worker0'), { status: 'busy' });
  assert.deepEqual(await h.workDone('worker0', 2), { ok: true });
  const r = await h.inFlight();
  assert.deepEqual(r.map((m) => [m.from, m.to, m.action, m.data]), [['worker0', 'run', 'Report', { task: 0, outcome: 'completed', items: 2 }]]);
  await h.deliverAll();
  assert.deepEqual(await h.run(), view('running', 'completed', 'assigned', false, false, 2));
  await h.workDone('worker1', 1);
  await h.deliverAll();
  assert.deepEqual(await h.run(), view('completed', 'completed', 'completed', false, false, 3));
});

test('cancel with one done in flight', async () => {
  const h = await createHost();
  await h.start();
  await h.deliverAll();
  await h.workDone('worker0', 1);
  assert.deepEqual(await h.cancel(), { ok: true });
  assert.equal((await h.cancel()).ok, false);
  const msgs = await h.inFlight();
  assert.equal(msgs.length, 3);
  await h.deliverAll();
  assert.deepEqual(await h.run(), view('cancelled', 'completed', 'cancelled', false, false, 1));
  assert.deepEqual(await h.worker('worker0'), { status: 'idle' });
});

test('cancelled and failed reports carry 0 items', async () => {
  const h = await createHost();
  await h.start();
  await h.deliverAll();
  await h.workFailed('worker1');
  await h.cancel();
  const msgs = (await h.inFlight()).filter((m) => m.action === 'Report');
  assert.deepEqual(msgs.map((m) => m.data), [{ task: 1, outcome: 'failed', items: 0 }]);
  await h.deliverAll();
  assert.deepEqual(await h.run(), view('failed', 'cancelled', 'failed'));
});

test('retry then fail', async () => {
  const h = await createHost();
  await h.start();
  await h.deliverAll();
  await h.workFailed('worker1');
  await h.deliverAll();
  assert.deepEqual(await h.run(), view('running', 'assigned', 'assigned', false, true));
  assert.deepEqual(await h.worker('worker1'), { status: 'busy' });
  await h.workFailed('worker1');
  await h.deliverAll();
  assert.deepEqual(await h.run(), view('running', 'assigned', 'failed', false, true));
  await h.workDone('worker0', 2);
  await h.deliverAll();
  assert.deepEqual(await h.run(), view('failed', 'completed', 'failed', false, true, 2));
});

test('retry then complete', async () => {
  const h = await createHost();
  await h.start();
  await h.deliverAll();
  await h.workFailed('worker0');
  await h.deliverAll();
  await h.workDone('worker0', 2);
  await h.workDone('worker1', 2);
  await h.deliverAll();
  assert.deepEqual(await h.run(), view('completed', 'completed', 'completed', true, false, 4));
});

test('timeout', async () => {
  const h = await createHost();
  assert.equal((await h.taskTimeout(0)).ok, false);
  await h.start();
  await h.deliverAll();
  assert.equal((await h.taskTimeout(2)).ok, false);
  assert.deepEqual(await h.taskTimeout(0), { ok: true });
  assert.equal((await h.taskTimeout(0)).ok, false);
  assert.deepEqual(await h.run(), view('running', 'failed', 'assigned'));
  await h.workDone('worker1', 1);
  await h.deliverAll();
  assert.deepEqual(await h.worker('worker0'), { status: 'idle' });
  assert.deepEqual(await h.run(), view('failed', 'failed', 'completed', false, false, 1));
});

test('late completed report after timeout adds nothing', async () => {
  const h = await createHost();
  await h.start();
  await h.deliverAll();
  await h.workDone('worker0', 2);
  await h.taskTimeout(0);
  assert.equal((await h.run()).status, 'running');
  await h.deliverAll();
  assert.deepEqual(await h.run(), view('running', 'failed', 'assigned'));
  await h.taskTimeout(1);
  assert.deepEqual(await h.run(), view('failed', 'failed', 'failed'));
});

